mapper.select:
select pqd.sheets as sheets
from prj_quotation q
         LEFT JOIN prj_quotation_details pqd
                   ON pqd.quotation_id = q.quotation_id
where q.source_document_category=#{sourceDocumentCategory}
  and q.source_document_id=#{sourceDocumentId}
  and q.quotation_id = #{quotationId}
  and q.price_list=#{priceList}
  and  q.data_class=#{dataClass}
  and pqd.sheets is not null
UNION ALL
select pl.SHEETS as sheets
from hls_price_list pl
where pl.PRICE_LIST=#{priceList}

SELECT ( SELECT l.DESCRIPTION FROM hls_price_list l WHERE l.price_list = t1.price_list ) AS price_list_desc, --(select max(c2.due_date) from con_contract_cashflow c2 where c2.contract_id = t1.source_document_id ) as lease_end_date, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'HLS500_ANNUAL_PAY_TIMES' and sc.code_value = to_char(t1.annual_pay_times)) AS annual_pay_times_desc, (select qd.sheets from prj_quotation_details qd where qd.quotation_id=t1.quotation_id) sheets, (select hpd.definition_name from hls_product_definition hpd where hpd.definition_id = t1.plan_id) plan_id_n, (select bt.description from hls_business_type bt where bt.document_category ='PRJ_PROJECT' and bt.business_type = t1.business_type) business_type_n, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' and t1.repay_flag = v.code_value) repay_flag_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ.PAYMENT_METHOD1' AND v.code_value = t1.payment_type) payment_type_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'SYS.YES_NO' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = T1.int_rate_calc_flag) int_rate_calc_flag_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'DISCOUNT_TIMES' AND B1.CODE_ID = B2.CODE_ID AND to_char(B2.VALUE) = to_char(T1.rental_discount_times)) rental_discount_times_n, (SELECT B2.MEANING FROM SYS_CODE_B B1, SYS_CODE_VALUE_B B2 WHERE B1.CODE = 'CHARGE_DISCOUNT_RULE' AND B1.CODE_ID = B2.CODE_ID AND B2.VALUE = T1.lease_charge_discount_rule) lease_charge_discount_rule_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'GRACE_TYPE' AND v.code_value = T1.grace_type)grace_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ.ACCEPTANCE_TERM' AND v.code_value = T1.acceptance_term) acceptance_term_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SYS.YES_NO' AND v.code_value = T1.calc_check_flag) calc_check_flag_n, t1.* FROM prj_quotation t1
1=1
and t1.source_document_id = #{sourceDocumentId}
and t1.quotation_id = #{quotationId}
and t1.document_id = #{documentId}
and t1.source_document_category = #{sourceDocumentCategory}
and t1.data_class = #{dataClass}

SELECT nvl((SELECT max(cwo.write_off_date) FROM con_contract cc, csh_write_off cwo WHERE quotation_id = pq.quotation_id and cwo.contract_id=cc.contract_id and cwo.write_off_type='PAYMENT_DEBT' ),'') as pay_due_date, pq.*, (select hpl.DESCRIPTION from hls_price_list hpl where hpl.PRICE_LIST=pq.PRICE_LIST) as PRICE_LIST_desc, '设备款' as cf_item_desc, (select cba.bank_account_name from csh_bank_account cba where cba.bank_account_id=pq.return_account) as return_account_name, (select cba.bank_account_num from csh_bank_account cba where cba.bank_account_id=pq.return_account) as return_account_num, ( SELECT hds.description FROM hls_document_status hds WHERE hds.document_category = 'FCT_PROJECT' AND hds.status_code = pq.payment_status ) AS payment_status_desc, (select cb.contract_id from con_contract cb where cb.quotation_id=pq.quotation_id and cb.data_class='NORMAL') as contract_id FROM prj_quotation pq
1=1
and pq.source_document_id = #{sourceDocumentId}
and pq.document_id = #{documentId}
and pq.source_document_category = #{sourceDocumentCategory}
and (pq.data_class = #{dataClass} or pq.data_class = 'VIRTUAL_CON')
and pq.payment_status = #{paymentStatus}
and pq.selected_flag = #{selectedFlag}

SELECT nvl((SELECT max(cwo.write_off_date) FROM con_contract cc, csh_write_off cwo WHERE quotation_id = pq.quotation_id and cwo.contract_id=cc.contract_id and cwo.write_off_type='PAYMENT_DEBT' ),'') as pay_due_date, pq.*, (select hpl.DESCRIPTION from hls_price_list hpl where hpl.PRICE_LIST=pq.PRICE_LIST) as PRICE_LIST_desc, '设备款' as cf_item_desc, (select cba.bank_branch_name from csh_bank_account cba where cba.bank_account_id=pq.return_account) as return_account_name, (select cba.bank_account_num from csh_bank_account cba where cba.bank_account_id=pq.return_account) as return_account_num, ( SELECT hds.description FROM hls_document_status hds WHERE hds.document_category = 'FCT_PROJECT' AND hds.status_code = pq.payment_status ) AS payment_status_desc, (select cb.contract_id from con_contract cb where cb.quotation_id=pq.quotation_id and cb.data_class='NORMAL') as contract_id, (select cb.contract_status from con_contract cb where cb.quotation_id=pq.quotation_id and cb.data_class='NORMAL') as contract_status FROM prj_quotation pq
1=1
and pq.source_document_id = #{sourceDocumentId}
and pq.document_id = #{documentId}
and pq.source_document_category = #{sourceDocumentCategory}
and (pq.data_class = #{dataClass} or pq.data_class = 'VIRTUAL_CON')
