SELECT pq.*, ccc.due_amount as amount, (select hpl.DESCRIPTION from hls_price_list hpl where hpl.PRICE_LIST=pq.PRICE_LIST) as PRICE_LIST_desc, '设备款' as cf_item_desc, ( SELECT hds.description FROM hls_document_status hds WHERE hds.document_category = 'FCT_PROJECT' AND hds.status_code = pq.payment_status ) AS payment_status_desc, cc.contract_id, ccc.cashflow_id FROM prj_quotation pq, con_contract cc, con_contract_cashflow ccc
pq.quotation_id=cc.quotation_id and ccc.contract_id=cc.contract_id and ccc.cf_direction='OUTFLOW' and cc.data_class='NORMAL'
