e pqc.cf_item = 91 and pqc.quotation_id = pq.quotation_id) paynote_term_n, pq.paynote_acceptance_date, --pq.paynote_charge_ratio, (select wm_concat(case when pqc.paynote_charge_rate is not null then pqc.paynote_charge_rate * 100 || '%' else '' end) from prj_quotation_cashflow pqc left join prj_quotation_cashflow py on pqc.source_cashflow_id = py.quotation_cashflow_id where pqc.cf_item = 91 and pqc.quotation_id = pq.quotation_id) paynote_charge_ratio_n, pq.paynote_charge, pq.net_paynote_charge, pq.vat_paynote_charge, pq.total_days, pq.pmt_discount_rate, pq.lpr_base_date, pq.lpr_fixed_date, pq.lpr_adjustment_term, pq.lpr_adjustment_period, pq.next_adjustment_date, pq.next_interest_rate, pq.exchange_rate, pq.deposit_settlement_method, pq.deposit_settlement_date, pq.mgt_fee_amortization_method, pq.asset_mgt_rate, pq.asset_mgt_total, pq.interest_amortization_method, pq.lease_charge_amort_method, pq.adv_service_amort_method, pq.holiday_adjust, pq.source_quotation_id, pq.payment_times, pq.calc_name, pq.tax_structure, pq.first_pay, pq.pre_lease_flag, pq.grace_flag, pq.vatable_rate_flag, pq.vatable_prin_flag, pq.asset_mgt_fee_type, pq.rental_rounding_type, pq.lease_end_date, pq.calc_date_type, pq.rental_pay_date, pq.float_type, pq.lpr_name_date, pq.price_list_type, pq.lpr_ref_day, pq.if_modify_firstdate, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.int_rate_type and scb.CODE = 'CON.INT_RATE_TYPE') as int_rate_type_desc, (select s.MEANING value_name from sys_code_value_b_v s where s.code = 'CON.INT_RATE_TYPE' and UPPER(s.code_value) = UPPER(nvl(pq.int_rate_type, 'FIXED'))) int_rate_type_n, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.floating_way and scb.CODE = 'FCT.FLOATING_WAY') as floating_way_desc, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.renting_method an