select pq.quotation_id, pq.source_document_category, pq.document_id, pq.payment_number, pq.payment_status, pq.payment_confirm_status, pq.data_class, pq.source_document_id, pq.description, pq.status, pq.price_list, pq.lease_start_date, pq.lease_times, pq.annual_pay_times, pq.lease_term, pq.pay_type, pq.currency, pq.tax_type_id, pq.vat_flag, pq.vat_rate, pq.lease_item_amount, pq.vat_input, pq.vat_input_tax_type_id, pq.vat_input_tax_type_rate, pq.down_payment_ratio, pq.down_payment, pq.net_down_payment, pq.vat_down_payment, pq.finance_amount, pq.finance_amount_upp, pq.net_finance_amount, pq.vat_finance_amount, pq.total_rental, pq.net_total_rental, pq.vat_total_rental, pq.total_interest, pq.net_total_interest, pq.vat_total_interest, (select nvl((sum(pqc.due_amount) / pq.finance_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 3) lease_charge_ratio, pq.lease_charge, pq.net_lease_charge, pq.vat_lease_charge, pq.lease_mgt_fee_ratio, pq.lease_mgt_fee, pq.net_lease_mgt_fee, pq.vat_lease_mgt_fee, pq.lease_mgt_fee_rule, (select nvl((sum(pqc.due_amount) / pq.finance_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item in (51,53)) deposit_ratio, pq.deposit, pq.deposit_upp, pq.deposit_deduction, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.deposit_deduction and scb.CODE = 'PRJ.MARGIN_PAYMENT_METHOD')deposit_deduction_n, pq.residual_ratio, pq.residual_value, pq.net_residual_value, pq.vat_residual_value, pq.balloon_ratio, pq.balloon, pq.net_balloon, pq.vat_balloon, pq.base_rate_type, pq.base_rate, pq.int_rate, pq.int_rate_implicit, pq.int_rate_type, pq.irr, pq.irr_after_tax, pq.pmt, pq.pmt_first, pq.billing_profile, pq.penalty_profile, pq.annual_mean_rate, pq.floating_range_method, pq.credit_amount, pq.floating_way_rate, pq.floating_way, pq.vat_down_payment_rate, pq.estimate_renting_date, pq.adv_service_fee_ratio, pq.renting_frequency, pq.par_interest_rate, pq.renting_method, pq.deposit_return_method, pq.xirr, pq.adv_service_fee, pq.final_residual_value, pq.fine_status, pq.selected_flag, pq.generated_status, pq.return_account, pq.interest_year_days, pq.object_version_number, pq.request_id, pq.program_id, pq.created_by, pq.creation_date, pq.last_updated_by, pq.last_update_date, pq.last_update_login, pq.billing_method, pq.business_type, pq.lease_term_m, pq.irr_without_fee, pq.xirr_without_fee_aft, pq.tax_type_code, pq.first_rental_payment_date, pq.payment_day, pq.payment_method, pq.assets_surplus_value, pq.insurance_fee_method, pq.insurance_fee, pq.adv_servicing_frequency, pq.lease_charging_frequency, pq.change_date, pq.first_rental_pay_change_date, pq.account_lease_date, pq.quotation_number, pq.quotation_type, pq.totle_pri, pq.balance_pri, pq.rent_payment_type, pq.delay_rent_status, pq.delay_rent_date, pq.adjust_delay_rent_date, pq.pre_lease_term, pq.prerent_payment_fre, pq.grace_lease_term, pq.first_phase_lease, pq.payment_first, pq.lpr_link_date, pq.pricing_floating_cycle, pq.total_management, pq.asset_management_rate, pq.lease_account_date, pq.buyback_price, pq.other_price, pq.subject_matter_introdution, pq.lease_account_date_delay, pq.first_release_date, pq.xirr_net, pq.xirr_paynote, pq.xirr_net_paynote, pq.paynote_ratio, pq.paynote_amount, pq.net_paynote_amount, pq.vat_paynote_amount, pq.paynote_term, pq.paynote_acceptance_date, pq.paynote_charge_ratio, pq.paynote_charge, pq.net_paynote_charge, pq.vat_paynote_charge, pq.total_days, pq.pmt_discount_rate, pq.lpr_base_date, pq.lpr_fixed_date, pq.lpr_adjustment_term, pq.lpr_adjustment_period, pq.next_adjustment_date, pq.next_interest_rate, pq.exchange_rate, pq.deposit_settlement_method, pq.deposit_settlement_date, pq.mgt_fee_amortization_method, pq.asset_mgt_rate, pq.asset_mgt_total, pq.interest_amortization_method, pq.lease_charge_amort_method, pq.adv_service_amort_method, pq.holiday_adjust, pq.source_quotation_id, pq.payment_times, pq.calc_name, pq.tax_structure, pq.first_pay, pq.pre_lease_flag, pq.grace_flag, pq.vatable_rate_flag, pq.vatable_prin_flag, pq.asset_mgt_fee_type, pq.rental_rounding_type, pq.lease_end_date, pq.calc_date_type, pq.rental_pay_date, pq.float_type, pq.lpr_name_date, pq.price_list_type, pq.lpr_ref_day, pq.if_modify_firstdate, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.int_rate_type and scb.CODE = 'CON.INT_RATE_TYPE') as int_rate_type_desc, (select s.MEANING value_name from sys_code_value_b_v s where s.code = 'CON.INT_RATE_TYPE' and UPPER(s.code_value) = UPPER(pq.int_rate_type)) int_rate_type_n, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.floating_way and scb.CODE = 'FCT.FLOATING_WAY') as floating_way_desc, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.renting_frequency and scb.CODE = 'PRJ.INTEREST_CYCLE') as renting_frequency_desc, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.renting_method and scb.CODE = 'PRJ.INTEREST_TYPE') as renting_method_desc, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.deposit_return_method and scb.CODE = 'PRJ.MARGIN_PAYMENT_METHOD') as deposit_return_method_desc, (select a.description from hls_business_type a where a.document_category = 'PRJ_PROJECT' and a.business_type = pq.business_type) business_type_n, (select fc.currency_name from fnd_currency fc where fc.currency_code = pq.currency) currency_n, (select h.description value_name from hls_price_list h where h.price_list = pq.price_list) price_list_n, nvl((select sum(pp.contract_amount) from prj_quotation pq2, prj_project pp where pq2.source_quotation_id = pq.quotation_id and pq2.source_document_id = pp.project_id and pp.data_class = 'VIRTUAL_CON' and pp.contract_status != 'CANCEL'), 0) as use_amount, (pq.finance_amount - nvl((select sum(pp.contract_amount) from prj_quotation pq2, prj_project pp where pq2.source_quotation_id = pq.quotation_id and pq2.source_document_id = pp.project_id and pp.data_class = 'VIRTUAL_CON' and pp.contract_status != 'CANCEL'), 0)) as left_amount from prj_quotation_history pq
1=1
and pq.source_document_category = #{sourceDocumentCategory}
and pq.data_class = #{dataClass}
and pq.source_document_id = #{sourceDocumentId}
and pq.version_id = #{versionId}

select pq.*, pq.description base_rate_n, nvl(pq.LEASE_ITEM_AMOUNT, 0) - nvl(pq.DOWN_PAYMENT, 0)project_principal,--项目本金 nvl(pq.LEASE_ITEM_AMOUNT, 0) - nvl(pq.DOWN_PAYMENT, 0) - nvl(pq.DEPOSIT, 0)risk_exposure,--风险敞口 (case when pq.payment_method = 'DAILY_INTEREST' then round(pq.INT_RATE / 360, 10) when pq.payment_method = 'TIMES_INTEREST' then round(pq.INT_RATE / 360, 10) end) daily_interest_rate, (select fe.name from sys_user su,fnd_employee fe where su.user_id=pq.created_by and fe.employee_code=su.user_name and rownum=1) create_name, (select distinct(fu.unit_name) from sys_user_allocation sa,fnd_employee_assigns fa,fnd_org_unit fu where sa.employee_assign_id = fa.employee_assign_id and fa.unit_id = fu.unit_id and sa.user_id = pq.created_by and sa.company_id = #{request.companyId}) create_unit_name, (select sum(nvl(pqc.DUE_AMOUNT, 0)) from PRJ_QUOTATION_CASHFLOW pqc where pqc.QUOTATION_ID = pq.QUOTATION_ID and pqc.CF_ITEM = 1)total_con_due_amount, (select sum(nvl(pqc.INTEREST, 0)) from PRJ_QUOTATION_CASHFLOW pqc where pqc.QUOTATION_ID = pq.QUOTATION_ID and pqc.CF_ITEM = 1)total_con_interest, ( SELECT l.DESCRIPTION FROM hls_price_list l WHERE l.price_list = pq.price_list ) AS price_list_n, ( select fc.currency_name from fnd_currency fc where fc.currency_code = pq.currency ) as currency_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'PRJ.INTEREST_CYCLE' and scvb.value = to_char(pq.adv_servicing_frequency) ) as adv_servicing_frequency_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'PRJ.INTEREST_CYCLE' and scvb.value = to_char(pq.renting_frequency) ) as renting_frequency_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.int_rate_type and scb.CODE='CON.INT_RATE_TYPE' ) as int_rate_type_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.floating_way and scb.CODE='PRJ.FLOATING_WAY' ) as floating_way_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.renting_method and scb.CODE='PRJ.INTEREST_TYPE' ) as renting_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.payment_method and scb.CODE='CON.PAYMENT_METHOD' ) as payment_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.deposit_return_method and scb.CODE='PRJ.MARGIN_PAYMENT_METHOD' ) as deposit_return_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.insurance_fee_method and scb.CODE='CON.INSURANCE_FEE_METHOD' ) as insurance_fee_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.lease_charging_frequency and scb.CODE='PRJ.INTEREST_CYCLE' ) as lease_charging_frequency_n, (SELECT scvb.MEANING FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.delay_rent_status and scb.CODE = 'SYS.YES_NO') as delay_rent_status_n from PRJ_QUOTATION pq
and pq.source_document_id=#{sourceDocumentId}
and pq.source_document_category=#{sourceDocumentCategory}
and pq.quotation_id=#{quotationId}

select pq.* from PRJ_QUOTATION pq
1=1 and pq.source_document_category='PRJ_PROJECT'
