select pq.*, nvl(pq.LEASE_ITEM_AMOUNT, 0) - nvl(pq.DOWN_PAYMENT, 0)project_principal,--项目本金 nvl(pq.LEASE_ITEM_AMOUNT, 0) - nvl(pq.DOWN_PAYMENT, 0) - nvl(pq.DEPOSIT, 0)risk_exposure,--风险敞口 (case when pq.payment_method = 'DAILY_INTEREST' then round(pq.INT_RATE / 360 * 365, 4) when pq.payment_method = 'TIMES_INTEREST' then round(pq.INT_RATE / 360, 4) end) daily_interest_rate, (select sum(nvl(ccc.DUE_AMOUNT, 0)) from con_contract_cashflow ccc where ccc.contract_id =pq.source_document_id and ccc.CF_ITEM = 1)total_con_due_amount, (select sum(nvl(ccc.INTEREST, 0)) from con_contract_cashflow ccc where ccc.contract_id =pq.source_document_id and ccc.CF_ITEM = 1)total_con_interest, ( SELECT l.DESCRIPTION FROM hls_price_list l WHERE l.price_list = pq.price_list ) AS price_list_desc, ( select fc.currency_name from fnd_currency fc where fc.currency_code = pq.currency ) as currency_name, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'PRJ.INTEREST_CYCLE' and scvb.value = pq.adv_servicing_frequency ) as adv_servicing_fre_desc, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'PRJ.INTEREST_CYCLE' and scvb.value = pq.renting_frequency ) as renting_frequency_desc, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.int_rate_type and scb.CODE='CON.INT_RATE_TYPE' ) as int_rate_type_desc, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.floating_way and scb.CODE='PRJ.FLOATING_WAY' ) as floating_way_desc, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.renting_method and scb.CODE='PRJ.INTEREST_TYPE' ) as renting_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.payment_method and scb.CODE='CON.PAYMENT_METHOD' ) as payment_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.deposit_return_method and scb.CODE='PRJ.MARGIN_PAYMENT_METHOD' ) as deposit_return_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.insurance_fee_method and scb.CODE='CON.INSURANCE_FEE_METHOD' ) as insurance_fee_method_n, ( select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID=scb.CODE_ID and scvb.VALUE=pq.lease_charging_frequency and scb.CODE='PRJ.INTEREST_CYCLE' ) as lease_charging_fre_desc, pq.change_date, pq.first_rental_pay_change_date, pq.source_document_category from PRJ_QUOTATION pq
1=1 and rownum=1
and pq.source_document_id=#{sourceDocumentId}
and pq.source_document_category=#{sourceDocumentCategory}
and pq.data_class=#{dataClass}
and pq.quotation_id=#{quotationId}

select pq.quotation_id, cc.project_id, cc.contract_id, pq.lease_start_date , pq.delay_rent_status , pq.delay_rent_date, cc.contract_number, pp.project_name, pp.project_number, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'SYS.YES_NO' and scv.value = pq.delay_rent_status) delay_rent_status_n, pq.adjust_delay_rent_date from prj_quotation pq, prj_project pp,con_contract cc
cc.project_id = pp.project_id and pq.source_document_id = cc.project_id --and cc.data_class = 'NORMAL'
and pq.source_document_id=#{sourceDocumentId}
and pq.source_document_category=#{sourceDocumentCategory}
and cc.data_class=#{dataClass}
and pq.quotation_id=#{quotationId}

SELECT t1.* FROM ( SELECT t.contract_id, p.contract_number AS contract_number_con, p.project_id, t.quotation_id, t.contract_name, t.contract_number, t.next_adjustment_date, ( SELECT b.bp_name FROM hls_bp_master b WHERE b.bp_id = t.tenant_id ) bp_name, p.project_number, p.project_name, q.price_list, q.description, ( SELECT h.description FROM hls_price_list h WHERE h.price_list = q.price_list ) price_list_n, ( SELECT hpl.adjust_rate_price FROM hls_price_list hpl WHERE hpl.price_list = q.price_list ) AS adjust_rate_price, ( SELECT hpl.adjust_rate_description FROM hls_price_list hpl WHERE hpl.price_list = q.price_list ) AS adjust_rate_description, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.host_unit_id ) AS unit_name, ( SELECT fc.company_full_name FROM fnd_company fc WHERE fc.company_id = p.company_spv ) AS company_name, p.FLOATING_RANGE_METHOD, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc. CODE = 'CON.FLOATING_RANGE_METHOD' AND sc.enabled_flag = 'Y' AND sc.code_value = p.FLOATING_RANGE_METHOD ) lpr_adjustment_period_n, q.finance_amount, q.lease_start_date, q.lease_term, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s. CODE = 'CON.INT_RATE_TYPE' AND upper(s.code_value) = upper(q.int_rate_type) ) int_rate_type_n, q.float_type, q.floating_way_rate, q.base_rate, q.base_rate_type, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s. CODE = 'FND.BASE_RATE_TYPE' AND s.code_value = q.base_rate_type ) base_rate_type_n, q.int_rate, ( SELECT max(cfr.flt_req_ln_id) FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf WHERE cfr.flt_req_id = cf.flt_req_id AND cfr.quotation_id = q.quotation_id AND cfr.contract_id = t.contract_id AND cfr. STATUS IN ('CALCULATED', 'FAILURE') ) flt_req_ln_id, ( SELECT a. STATUS FROM con_floating_rate_req_ln a WHERE a.flt_req_ln_id = ( SELECT max(cfr.flt_req_ln_id) AS flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf WHERE cfr.flt_req_id = cf.flt_req_id AND cfr.quotation_id = q.quotation_id AND cfr.contract_id = t.contract_id AND cfr. STATUS IN ('CALCULATED', 'FAILURE') ) ) AS STATUS, ( SELECT scvb.meaning FROM con_floating_rate_req_ln a, sys_code_b scb, sys_code_value_b scvb WHERE a.flt_req_ln_id = ( SELECT max(cfr.flt_req_ln_id) AS flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf WHERE cfr.flt_req_id = cf.flt_req_id AND cfr.quotation_id = q.quotation_id AND cfr.contract_id = t.contract_id AND cfr. STATUS IN ('CALCULATED', 'FAILURE') ) AND scb.code_id = scvb.code_id AND scvb. VALUE = a. STATUS AND scb. CODE = 'CON.FLOATING_REQ_LN_STATUS' AND scb.enabled_flag = 'Y' AND scvb.enabled_flag = 'Y' ) AS status_n, ( SELECT a.flt_req_id FROM con_floating_rate_req_ln a WHERE a.flt_req_ln_id = ( SELECT max(cfr.flt_req_ln_id) AS flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf WHERE cfr.flt_req_id = cf.flt_req_id AND cfr.quotation_id = q.quotation_id AND cfr.contract_id = t.contract_id AND cfr. STATUS IN ('CALCULATED', 'FAILURE') ) ) AS flt_req_id, q.BASE_RATE_COLLECT, ( SELECT fa.DESCRIPTION FROM fnd_base_rate_set fa WHERE fa.BASE_RATE_SET = q.BASE_RATE_COLLECT ) BASE_RATE_COLLECT_n, ( SELECT max(t3.BASE_RATE_SET) FROM fnd_base_rate_set t3 WHERE t3.VALID_FROM <= sysdate AND t3.base_rate_type = 'LPR' ) BASE_RATE_COLLECT_new, ( SELECT fa.DESCRIPTION FROM fnd_base_rate_set fa WHERE fa.BASE_RATE_SET = ( SELECT max(t3.BASE_RATE_SET) FROM fnd_base_rate_set t3 WHERE t3.VALID_FROM <= sysdate AND t3.base_rate_type = 'LPR' ) ) BASE_RATE_COLLECT_new_n, ( SELECT t1.base_rate FROM fnd_base_rate t1, fnd_base_rate_set t2 WHERE t1.BASE_RATE_SET = t2.BASE_RATE_SET AND t2.BASE_RATE_SET = ( SELECT max(t3.BASE_RATE_SET) FROM fnd_base_rate_set t3 WHERE t3.VALID_FROM <= sysdate AND t3.base_rate_type = 'LPR' ) AND t1.DESCRIPTION = q.BASE_RATE_TYPE ) new_base_rate, ( ( nvl(q.FLOATING_WAY_RATE, 0) / 10000 ) + ( SELECT t1.base_rate FROM fnd_base_rate t1, fnd_base_rate_set t2 WHERE t1.BASE_RATE_SET = t2.BASE_RATE_SET AND t2.BASE_RATE_SET = ( SELECT max(t3.BASE_RATE_SET) FROM fnd_base_rate_set t3 WHERE t3.VALID_FROM <= sysdate AND t3.base_rate_type = 'LPR' ) AND t1.DESCRIPTION = q.BASE_RATE_TYPE ) ) new_int_rate, ( SELECT a.quotation_id_new FROM con_floating_rate_req_ln a WHERE a.flt_req_ln_id = ( SELECT max(cfr.flt_req_ln_id) AS flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf WHERE cfr.flt_req_id = cf.flt_req_id AND cfr.quotation_id = q.quotation_id AND cfr.contract_id = t.contract_id AND cfr. STATUS IN ('CALCULATED', 'FAILURE') ) ) quotation_id_new, ( SELECT cf.status FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf WHERE cfr.flt_req_id = cf.flt_req_id AND cfr.quotation_id = q.quotation_id AND cfr.contract_id = t.contract_id AND cfr. STATUS IN ('CALCULATED', 'FAILURE') and rownum=1 order by cfr.flt_req_ln_id ) flt_status, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.code_id = scvb.code_id AND scvb.VALUE= ( SELECT cf.status FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf WHERE cfr.flt_req_id = cf.flt_req_id AND cfr.quotation_id = q.quotation_id AND cfr.contract_id = t.contract_id AND cfr. STATUS IN ('CALCULATED', 'FAILURE') and rownum=1 order by cfr.flt_req_ln_id ) AND scb. CODE = 'CON.FLOATING_REQ_hd_STATUS' AND scb.enabled_flag = 'Y' AND scvb.enabled_flag = 'Y' ) flt_status_n FROM con_contract t, prj_quotation q, prj_project p WHERE t.data_class = 'NORMAL' AND t.project_id = p.project_id AND t.quotation_id = q.QUOTATION_ID AND t.contract_status = 'INCEPT' AND q.int_rate_type = 'FLOATING' -- AND t.next_adjustment_date <= sysdate AND NOT EXISTS ( SELECT 1 FROM con_floating_rate_req_ln cfr WHERE cfr.quotation_id = t.quotation_id AND t.contract_id = cfr.contract_id AND cfr. STATUS != 'CALCULATED' ) AND EXISTS( SELECT 1 FROM con_contract_cashflow ccc WHERE t.CONTRACT_ID = ccc.CONTRACT_ID AND ccc.CF_DIRECTION = 'INFLOW')
