select * from (SELECT
cc.contract_number, pp.contract_number as contract_number_con, pp.host_unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou where fou.unit_id = pp.host_unit_id) as unit_name, (SELECT fc.company_full_name FROM fnd_company fc where fc.company_id = pp.company_spv) as company_name,
cc.contract_name, cc.contract_id, cc.contract_status, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.CONTRACT_STATUS' and s.code_value = cc.contract_status) contract_status_n, cc.next_adjustment_date, pp.project_id, pq.quotation_id, pq.lpr_link_date, date_add(pq.lpr_link_date ,interval pq.lpr_adjustment_term month) as interest_rate_day, pp.tenant_id, (SELECT wm_concat(hbm.bp_name) FROM prj_project_bp ppb, hls_bp_master hbm WHERE ppb.project_id = pp.project_id and ppb.bp_id = hbm.bp_id and ppb.bp_categroy = 'CON_CONTRACT' and ppb.Bp_Type in ('TENANT', 'TENANT_SEC')) AS bp_name, pp.project_number, pp.project_name, pq.description, pq.price_list, (select h.description from hls_price_list h where h.price_list = pq.price_list) price_list_n, (select hpl.adjust_rate_price from hls_price_list hpl where hpl.price_list = pq.price_list) as adjust_rate_price, (select hpl.adjust_rate_description from hls_price_list hpl where hpl.price_list = pq.price_list) as adjust_rate_description, pq.finance_amount, pq.first_release_date, pq.lease_start_date, pq.lease_term, pq.int_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.INT_RATE_TYPE' and upper(s.code_value) = upper(pq.int_rate_type)) int_rate_type_n, pq.float_type, pq.base_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'FND.BASE_RATE_TYPE' and s.code_value = pq.base_rate_type) base_rate_type_n, pq.base_rate, pq.floating_way_rate, pq.int_rate, pq.lpr_base_date, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'LPR_BASE_DATE' and s.code_value = pq.lpr_base_date) lpr_base_date_n, pq.lpr_fixed_date, pq.lpr_adjustment_term, pq.lpr_adjustment_period, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.FLOATING_RANGE_METHOD' and s.code_value = pq.lpr_adjustment_period) lpr_adjustment_period_n, (SELECT max(cfr.flt_req_ln_id) FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf where cfr.flt_req_id = cf.flt_req_id and cfr.quotation_id = pq.quotation_id and cfr.contract_id = cc.contract_id and cfr.status in ('CALCULATED' ,'FAILURE' ) ) flt_req_ln_id, (SELECT a.new_base_rate FROM con_floating_rate_req_ln a where a.flt_req_ln_id = (SELECT max(cfr.flt_req_ln_id) as flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf where cfr.flt_req_id = cf.flt_req_id and cfr.quotation_id = pq.quotation_id and cfr.contract_id = cc.contract_id and cfr.status in ('CALCULATED' ,'FAILURE' ))) as new_base_rate, (SELECT a.new_int_rate FROM con_floating_rate_req_ln a where a.flt_req_ln_id = (SELECT max(cfr.flt_req_ln_id) as flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf where cfr.flt_req_id = cf.flt_req_id and cfr.quotation_id = pq.quotation_id and cfr.contract_id = cc.contract_id and cfr.status in ('CALCULATED' ,'FAILURE' )) ) as new_int_rate, (SELECT a.quotation_id_new FROM con_floating_rate_req_ln a where a.flt_req_ln_id = (SELECT max(cfr.flt_req_ln_id) as flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf where cfr.flt_req_id = cf.flt_req_id and cfr.quotation_id = pq.quotation_id and cfr.contract_id = cc.contract_id and cfr.status in ('CALCULATED' ,'FAILURE' ) )) as quotation_id_new, (SELECT a.status FROM con_floating_rate_req_ln a where a.flt_req_ln_id = (SELECT max(cfr.flt_req_ln_id) as flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf where cfr.flt_req_id = cf.flt_req_id and cfr.quotation_id = pq.quotation_id and cfr.contract_id = cc.contract_id and cfr.status in ('CALCULATED' ,'FAILURE' ))) as status,
(SELECT scvb.meaning FROM con_floating_rate_req_ln a, sys_code_b scb, sys_code_value_b scvb where a.flt_req_ln_id = (SELECT max(cfr.flt_req_ln_id) as flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf where cfr.flt_req_id = cf.flt_req_id and cfr.quotation_id = pq.quotation_id and cfr.contract_id = cc.contract_id and cfr.status in ('CALCULATED' ,'FAILURE' )) and scb.code_id = scvb.code_id AND scvb.VALUE = a.status AND scb.CODE = 'CON.FLOATING_REQ_LN_STATUS' AND scb.enabled_flag = 'Y' AND scvb.enabled_flag = 'Y' ) as status_n, (SELECT a.flt_req_id FROM con_floating_rate_req_ln a where a.flt_req_ln_id = (SELECT max(cfr.flt_req_ln_id) as flt_req_ln_id FROM con_floating_rate_req_ln cfr, con_floating_rate_req cf where cfr.flt_req_id = cf.flt_req_id and cfr.quotation_id = pq.quotation_id and cfr.contract_id = cc.contract_id and cfr.status in ('CALCULATED' ,'FAILURE' ))) as flt_req_id
FROM con_contract cc left join prj_quotation pq on cc.contract_id = pq.source_document_id and pq.source_document_category = 'CON_CONTRACT' left join prj_project pp on cc.project_id = pp.project_id WHERE EXISTS (SELECT ct.contract_id FROM csh_transaction ct WHERE ct.contract_id = cc.contract_id AND ct.transaction_type = 'PAYMENT') ) v
