select cf.flt_req_id, cf.company_id, cf.flt_req_number , cf.flt_req_date, cf.flt_req_user_id, (case when cf.flt_req_user_id = -1 then '系統自动执行' else (select su.description from sys_user su where su.user_id = cf.flt_req_user_id) end) as flt_req_user_name, cf.creation_date, cf.last_update_date,
cfr.flt_req_ln_id, cfr.status, cfr.new_base_rate, cfr.quotation_id_new, cfr.new_int_rate,
cfr.lpr_link_date , cfr.next_adjustment_date, date_add( cfr.lpr_link_date ,interval v.lpr_adjustment_term month) as interest_rate_day,
(SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.code_id = scvb.code_id AND scvb.VALUE = cfr.STATUS AND scb.CODE = 'CON.FLOATING_REQ_LN_STATUS' AND scb.enabled_flag = 'Y' AND scvb.enabled_flag = 'Y') AS status_n,
(SELECT nvl(SUM(ccc.due_amount), 0) FROM prj_quotation_cashflow ccc WHERE ccc.quotation_id = cfr.quotation_id AND ccc.contract_id = cfr.contract_id AND ccc.cf_item IN (1, 10)) AS old_due_amount, (SELECT nvl(SUM(pqc.due_amount), 0) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = cfr.quotation_id_new AND cf_item IN (1, 10)) AS new_due_amount, (SELECT nvl(SUM(ccc.principal), 0) FROM prj_quotation_cashflow ccc WHERE ccc.quotation_id = cfr.quotation_id AND ccc.contract_id = cfr.contract_id AND ccc.cf_item IN (1, 10)) AS old_principal, (SELECT nvl(SUM(pqc.principal), 0) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = cfr.quotation_id_new AND pqc.cf_item IN (1, 10)) AS new_principal, (SELECT nvl(SUM(ccc.interest), 0) FROM prj_quotation_cashflow ccc WHERE ccc.quotation_id = cfr.quotation_id AND ccc.contract_id = cfr.contract_id AND ccc.cf_item IN (1, 10)) AS old_interest, (SELECT nvl(SUM(pqc.interest), 0) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = cfr.quotation_id_new AND pqc.cf_item IN (1, 10)) AS new_interest, (SELECT nvl(SUM(ccc.interest), 0) - nvl(SUM(ccc.received_amount), 0) FROM prj_quotation_cashflow ccc WHERE ccc.quotation_id = cfr.quotation_id AND ccc.contract_id = cfr.contract_id AND ccc.cf_item IN (1, 10) AND ccc.write_off_flag != 'NOT' ) AS old_outstanding_interest, (SELECT nvl(SUM(pqc.interest), 0) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = cfr.quotation_id_new AND pqc.cf_item IN (1, 10)) - (SELECT nvl(SUM(ccc.received_amount), 0) FROM con_contract_cashflow ccc WHERE ccc.quotation_id = cfr.quotation_id AND ccc.contract_id = cfr.contract_id AND ccc.cf_item IN (1, 10) AND ccc.write_off_flag != 'NOT') AS new_outstanding_interest, (SELECT nvl(SUM(pqc.interest), 0) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = cfr.quotation_id_new AND pqc.cf_item IN (1, 10)) - (SELECT nvl(SUM(ccc.interest), 0) FROM prj_quotation_cashflow ccc WHERE ccc.quotation_id = cfr.quotation_id AND ccc.contract_id = cfr.contract_id AND ccc.cf_item IN (1, 10)) AS interest_adj_amount,
v.*
from (SELECT
cc.contract_number, pp.contract_number as contract_number_con, pp.host_unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou where fou.unit_id = pp.host_unit_id) as unit_name, (SELECT fc.company_full_name FROM fnd_company fc where fc.company_id = pp.company_spv) as company_name,
cc.contract_name, cc.contract_id, cc.contract_status, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.CONTRACT_STATUS' and s.code_value = cc.contract_status) contract_status_n,
pp.project_id, pq.quotation_id,
pp.tenant_id, (SELECT wm_concat(hbm.bp_name ) FROM prj_project_bp ppb, hls_bp_master hbm WHERE ppb.project_id = pp.project_id and ppb.bp_id = hbm.bp_id and ppb.bp_categroy = 'CON_CONTRACT' and ppb.Bp_Type in ('TENANT', 'TENANT_SEC')) AS bp_name, pp.project_number, pp.project_name, pq.description, pq.price_list, (select h.description from hls_price_list h where h.price_list = pq.price_list) price_list_n, (select hpl.adjust_rate_price from hls_price_list hpl where hpl.price_list = pq.price_list) as adjust_rate_price, (select hpl.adjust_rate_description from hls_price_list hpl where hpl.price_list = pq.price_list) as adjust_rate_description, pq.finance_amount, pq.first_release_date, pq.lease_start_date, pq.lease_term, pq.int_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.INT_RATE_TYPE' and upper(s.code_value) = upper(pq.int_rate_type)) int_rate_type_n, pq.float_type, pq.base_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'FND.BASE_RATE_TYPE' and s.code_value = pq.base_rate_type) base_rate_type_n, pq.base_rate, pq.floating_way_rate, pq.int_rate, pq.lpr_base_date, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'LPR_BASE_DATE' and s.code_value = pq.lpr_base_date) lpr_base_date_n, pq.lpr_fixed_date, pq.lpr_adjustment_term, pq.lpr_adjustment_period, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.FLOATING_RANGE_METHOD' and s.code_value = pq.lpr_adjustment_period) lpr_adjustment_period_n FROM con_contract cc left join prj_quotation pq on cc.quotation_id = pq.quotation_id left join prj_project pp on cc.project_id = pp.project_id) v , con_floating_rate_req_ln cfr, con_floating_rate_req cf
v.quotation_id = cfr.quotation_id and cf.flt_req_id = cfr.flt_req_id AND cf.status = 'APPROVED'
and cf.flt_req_date >= #{fltReqDateFrom}
and cf.flt_req_date <= #{fltReqDateTo}
and cfr.next_adjustment_date >= #{nextAdjustmentDateFrom}
and cfr.next_adjustment_date <= #{nextAdjustmentDateTo}
and v.contract_number like #{contractNumber}
