ORDER BY IF ( isnull(cf.flt_req_date), 1, 0 ) DESC

select * from ( SELECT p.project_name, p.price_review_date, q.price_list, q.quotation_id, (SELECT m.bp_name FROM hls_bp_master m WHERE m.bp_id = p.tenant_id) bp_name, (SELECT sum(py.paynote_term) from prj_quotation_cashflow pqc left join prj_quotation_cashflow py on pqc.source_cashflow_id = py.quotation_cashflow_id where pqc.cf_item = 91 and pqc.quotation_id = q.quotation_id) paynote_term,
p.business_type, (SELECT t.description FROM hls_business_type t WHERE t.business_type = p.business_type AND t.document_category = p.document_category) business_type_n, (case when p.industry_category = 'FIRST_SPECIAL_INDUSTRY' then '一类专项行业', when p.industry_category = 'SECOND_SPECIAL_INDUSTRY' then '二类专项行业' else '其他' end) industry_category_n, (case when p.key_support_area = 'Y' then '重点支持区域 ' else '' end) || (case when p.green_leasing = 'Y', '绿色租赁业务 ' else '' end) || (case when p.epidemic_prevention = 'Y' else '防疫相关业务 ', '' end) || (case when p.nada = 'Y', '无 ' else '' end) AS special_category, (SELECT wm_concat(bp_name || ',' || v.meaning || ',' || (SELECT v.MEANING FROM hls_bp_credit_rate r, sys_code_value_b_v v WHERE v.code = 'HLS.EXTERNAL_RATING_RESULT' AND v.code_value = r.identification_result_o AND r.bp_id = b.bp_id and rownum=1)) FROM prj_project_bp b, hls_bp_master m, sys_code_value_b_v v WHERE b.project_id = p.project_id AND b.bp_categroy = 'PRJ_PROJECT' AND b.bp_type IN ('TENANT', 'TENANT_SEC', 'WARRANTOR', 'VENDER') AND v.code = 'STRATEGIC_BP_TYPE' AND v.code_value = m.strategic_bp_type AND b.bp_id = m.bp_id) AS bp_type_n,
(q.finance_amount/100000000)finance_amount, nvl((SELECT SUM(nvl(pqc.due_amount, 0)) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = q.quotation_id AND pqc.cf_item = 90), 0) draft_amount,
nvl((SELECT SUM(nvl(pqc.paynote_charge_fee, 0)) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = q.quotation_id AND pqc.cf_item = 90), 0) paynote_charge_fee, (SELECT nvl((SUM(pqc.due_amount) / q.finance_amount), 0) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = q.quotation_id AND pqc.cf_item IN (51, 53)) deposit_ratio, (SELECT nvl((SUM(pqc.due_amount) / q.finance_amount), 0) FROM prj_quotation_cashflow pqc WHERE pqc.quotation_id = q.quotation_id AND pqc.cf_item = 3) lease_charge_ratio, (SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = 'RENTING_FREQUENCY' AND v.code_value = q.renting_frequency) renting_frequency_n, round(q.xirr * 100, 2) || '%' xirr_n,
(select s.description from sys_user s where s.user_id = p.host_project_manager) host_project_manager_n, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = p.host_unit_id) host_unit_name, (select u.description from sys_user u where u.user_id = p.price_review_person)price_review_person_n FROM prj_project p, prj_quotation q WHERE p.data_class = 'NORMAL' AND p.data_type = 'NORMAL' AND q.source_document_category = 'PRJ_PROJECT' AND q.source_document_id = p.project_id and p.project_status = 'NOTICE_APPROVED' ORDER BY p.project_name) t
and t.project_name like #{projectName}
and t.bp_name like #{bpName}
and t.price_review_date = #{priceReviewDate}

SELECT pq.quotation_id , pq.change_ref_quotation_id FROM prj_quotation pq
pq.source_document_category = 'PRJ_PROJECT' and pq.source_document_id = #{sourceDocumentId}
order by quotation_id

select pq.quotation_id, pq.lease_item_amount, pq.rental_plan, pq.roa, pq.finance_amount, pq.lease_term, pq.first_rental_payment_date, pq.lease_start_date, pq.annual_pay_times, pq.RENTING_FREQUENCY, pq.vat_rate, pq.lease_mgt_fee_ratio, pq.lease_mgt_fee, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'RENTING_FREQUENCY' and s.code_value = to_char(pq.RENTING_FREQUENCY))renting_frequency_n, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'HLS500_ANNUAL_PAY_TIMES' and s.code_value = to_char(pq.annual_pay_times))annual_pay_times_n, pq.payment_day, pq.residual_value, pq.currency, (select fc.currency_name from fnd_currency fc where fc.currency_code = pq.currency)currency_n, pq.xirr, pq.XIRR_WITHOUT_FEE_AFT, pq.int_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.INT_RATE_TYPE' and upper(s.code_value) = upper(pq.int_rate_type))int_rate_type_n, pq.base_rate, pq.lpr_fixed_date, pq.lpr_link_date, pq.int_rate, pq.lpr_adjustment_term, pq.LPR_ADJUSTMENT_TERM pricing_floating_cycle, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 51 and pqc.cf_type = 5) deposit, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 3 and pqc.cf_type = 3) lease_charge, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 66 and pqc.cf_type = 65) adv_service_fee, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 41 and pqc.cf_type = 4) lease_mgt_fee, (case when nvl(pq.lease_item_amount,0) != 0 then ((select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 41 and pqc.cf_type = 4)/pq.lease_item_amount) else pq.lease_mgt_fee_ratio end) lease_mgt_fee_ratio, pq.description, pq.payment_number, pq.quotation_number, pq.price_list, (select h.description from hls_price_list h where h.price_list = pq.price_list)price_list_n, pq.price_list_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'PRICE_LIST_TYPE' and s.code_value = pq.price_list_type)price_list_type_n, pq.business_type, (select hbt.description from hls_business_type hbt where hbt.document_category = 'PRJ_PROJECT' and pq.business_type = hbt.business_type)business_type_n, pq.exchange_rate, pq.first_pay, pq.down_payment, pq.first_release_date, pq.pre_lease_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.pre_lease_flag)pre_lease_flag_n, pq.pre_lease_term, pq.grace_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.grace_flag)grace_flag_n, pq.grace_lease_term, pq.lease_end_date, pq.pay_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'PAY_TYPE' and s.code_value = to_char(pq.pay_type))pay_type_n, pq.base_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'FND.BASE_RATE_TYPE' and s.code_value = pq.base_rate_type)base_rate_type_n, pq.floating_way_rate, pq.tax_structure, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'TAX_STRUCTURE' and s.code_value = pq.tax_structure)tax_structure_n, pq.tax_type_code, pq.lpr_base_date, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'LPR_BASE_DATE' and s.code_value = pq.lpr_base_date)lpr_base_date_n, pq.lpr_adjustment_period, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.FLOATING_RANGE_METHOD' and s.code_value = pq.lpr_adjustment_period)lpr_adjustment_period_n, pq.asset_mgt_fee_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'ASSET_MGT_FEE_TYPE' and s.code_value = pq.asset_mgt_fee_type)asset_mgt_fee_type_n, pq.interest_amortization_method, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'GLD.AMORTIZATION_METHOD' and s.code_value = pq.interest_amortization_method)interest_amortization_method_n, pq.rental_rounding_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'RENTAL_ROUNDING_TYPE' and s.code_value = pq.rental_rounding_type)rental_rounding_type_n, pq.calc_date_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CALC_DATE_TYPE' and s.code_value = pq.calc_date_type)calc_date_type_n, pq.rental_pay_date, pq.lpr_ref_day, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'LPR_DATE_REF' and s.code_value = pq.lpr_ref_day)lpr_ref_day_n, pq.vatable_rate_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.vatable_rate_flag)vatable_rate_flag_n, pq.vatable_prin_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.vatable_prin_flag)vatable_prin_flag_n, pq.lpr_name_date, pq.xirr_net, pq.xirr_paynote, pq.xirr_net_paynote, pq.lease_times, pq.interest_year_days, pq.irr_after_tax, pq.irr, pq.total_rental, pq.total_interest, pq.apt_bill_ratio, pq.apt_bill_amount, pq.apt_bill_term, pq.lf_credit_ratio, pq.lf_credit_amount, pq.lf_credit_term, pq.cash_amount, pq.cash_ratio, pq.bonded_lease_flag, pq.base_rate_collect, (SELECT fb.description AS value_name FROM fnd_base_rate_set fb where fb.BASE_RATE_SET = pq.base_rate_collect) base_rate_collect_n, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.BONDED_LEASE_FLAG and scb.CODE = 'SYS.YES_NO') bonded_lease_flag_n, nvl(pq.deposit_deduction,'PERIOD_FINAL_DEDUCTIBLE'), (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = nvl(pq.deposit_deduction,'PERIOD_FINAL_DEDUCTIBLE') and scb.CODE = 'PRJ.MARGIN_PAYMENT_METHOD')deposit_deduction_n, pq.lease_charge_ratio, pq.deposit_ratio, pq.down_payment_ratio, pq.float_type, (SELECT t.description AS value_name FROM fnd_tax_type_code t WHERE t.enabled_flag = 'Y' and t.tax_type_code = pq.tax_type_code )tax_type_code_n, pq.payment_method, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'PRJ.PAYMENT_METHOD' and s.code_value = pq.payment_method) payment_method_n from PRJ_QUOTATION pq
1=1
and pq.source_Document_Id=#{sourceDocumentId}
and pq.source_document_category=#{sourceDocumentCategory}
and pq.quotation_id=#{quotationId}

SELECT pq.source_document_category, pq.document_id, ( SELECT concat( DOCUMENT_NUMBER, '-', nvl( ( SELECT LPAD( RIGHT ( max( pq1.payment_number ), 2 ) + 1, 2, 0 ) FROM prj_quotation pq1 WHERE pq1.DATA_CLASS = 'CONTRACT_PLAN' AND pq1.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND pq1.SOURCE_DOCUMENT_ID = fpa.PROJECT_ID ), '01' ) ) FROM fct_project_attachment fpa WHERE fpa.PROJECT_ID = 7530 AND fpa.MAJOR_CON_FLAG = 'Y' ) AS payment_number, pq.payment_status, CASE
WHEN pq.payment_status = 'NEW' THEN '新建' WHEN pq.payment_status = 'CONFIRM' THEN '已确认' END AS payment_status_n, pq.loan_type, ( SELECT scvb.MEANING FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scvb. VALUE = pq.loan_type AND scb.CODE = 'CSH.LOAN_TYPE' ) loan_type_n, pq.price_list, ( SELECT h.description value_name FROM hls_price_list h WHERE h.price_list = pq.price_list ) price_list_n FROM prj_quotation pq
1=1
and pq.source_document_category = #{sourceDocumentCategory}
and pq.data_class = #{dataClass}
and pq.source_document_id = #{sourceDocumentId}
and pq.quotation_id = #{quotationId}
order by pq.creation_date asc

SELECT pq.quotation_id, pp.project_id, -- 承租人 ( SELECT wm_concat ( hbm.bp_name ) FROM hls_bp_master hbm, prj_project_bp ppb WHERE ppb.bp_id = hbm.bp_id AND ppb.bp_type = 'TENANT' AND ppb.project_id = pp.project_id ) AS tenants, -- 租赁方式 pp.business_type, ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = pp.business_type AND hdt.document_category = pp.document_category AND hdt.document_type = pp.document_type ) AS business_type_n, -- 租赁金额 (暂去报价项目金额) pq.lease_item_amount, -- 租赁物信息 pp.lease_matter_note, -- 担保方式 pp.guarantee_method_note, -- 融资期限 pq.lease_term, -- 融资年利率 pq.int_rate, -- 保证金 pq.deposit, -- 还款方式 pq.pay_type, pq.PRICE_LIST, ( SELECT h.description value_name FROM hls_price_list h WHERE h.price_list = pq.price_list ) price_list_n, -- 手续费 pq.lease_charge, -- 留购价款 pq.residual_value, -- 内部收益率 pq.irr_after_tax, nvl( pq.irr, 0 ) irr, nvl( pq.xirr, 0 ) xirr, -- 资金用途 pp.finance_note, -- 其他 pp.other, pq.LEASE_START_DATE, ( CASE
WHEN pq.credit_grade IS NULL THEN ( SELECT max( credit_grade ) FROM prj_project_bp ppb LEFT JOIN HLS_BP_MASTER hbm ON ppb.bp_id = hbm.bp_id WHERE ppb.PROJECT_ID = pp.project_id ) ELSE pq.credit_grade END ) credit_grade, ( SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'RSC_CREDIT_RATING' AND scv.VALUE = to_char( CASE
WHEN pq.credit_grade IS NULL THEN ( SELECT max( credit_grade ) FROM prj_project_bp ppb LEFT JOIN HLS_BP_MASTER hbm ON ppb.bp_id = hbm.bp_id WHERE ppb.PROJECT_ID = pp.project_id ) ELSE pq.credit_grade END ) ) credit_grade_n FROM prj_quotation pq, prj_project pp WHERE pq.SOURCE_DOCUMENT_ID = pp.project_id and pp.project_id = #{projectId}
and pq.SOURCE_DOCUMENT_CATEGORY = #{sourceDocumentCategory}
order by pq.creation_date asc,pq.quotation_id

select pq.quotation_id, pq.lease_item_amount, pq.rental_plan, pq.roa, pq.finance_amount, pq.lease_term, pq.first_rental_payment_date, pq.lease_start_date, pq.annual_pay_times, pq.RENTING_FREQUENCY, pq.vat_rate, pq.lease_mgt_fee_ratio, pq.lease_mgt_fee, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'LON.INTEREST_CYCLE' and s.code_value = to_char(pq.RENTING_FREQUENCY))renting_frequency_n, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'HLS500_ANNUAL_PAY_TIMES' and s.code_value = to_char(pq.annual_pay_times))annual_pay_times_n, pq.payment_day, pq.residual_value, pq.currency, (select fc.currency_name from fnd_currency fc where fc.currency_code = pq.currency)currency_n, pq.xirr, pq.XIRR_WITHOUT_FEE_AFT, pq.int_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.INT_RATE_TYPE' and upper(s.code_value) = upper(pq.int_rate_type))int_rate_type_n, pq.base_rate, pq.lpr_fixed_date, pq.lpr_link_date, pq.int_rate, pq.lpr_adjustment_term, pq.LPR_ADJUSTMENT_TERM pricing_floating_cycle, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 51 and pqc.cf_type = 5) deposit, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 3 and pqc.cf_type = 3) lease_charge, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 66 and pqc.cf_type = 65) adv_service_fee, (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 41 and pqc.cf_type = 4) lease_mgt_fee, (case when nvl(pq.lease_item_amount,0) != 0 then ((select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = pq.quotation_id and pqc.cf_item = 41 and pqc.cf_type = 4)/pq.lease_item_amount) else pq.lease_mgt_fee_ratio end) lease_mgt_fee_ratio, pq.description, pq.payment_number, pq.quotation_number, pq.price_list, (select h.description from hls_price_list h where h.price_list = pq.price_list)price_list_n, pq.price_list_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'PRICE_LIST_TYPE' and s.code_value = pq.price_list_type)price_list_type_n, pq.business_type, (select hbt.description from hls_business_type hbt where hbt.document_category = 'PRJ_PROJECT' and pq.business_type = hbt.business_type)business_type_n, pq.exchange_rate, pq.first_pay, pq.down_payment, pq.first_release_date, pq.pre_lease_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.pre_lease_flag)pre_lease_flag_n, pq.pre_lease_term, pq.grace_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.grace_flag)grace_flag_n, pq.grace_lease_term, pq.lease_end_date, pq.pay_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'PAY_TYPE' and s.code_value = to_char(pq.pay_type))pay_type_n, pq.base_rate_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'FND.BASE_RATE_TYPE' and s.code_value = pq.base_rate_type)base_rate_type_n, pq.floating_way_rate, pq.tax_structure, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'TAX_STRUCTURE' and s.code_value = pq.tax_structure)tax_structure_n, pq.tax_type_code, pq.lpr_base_date, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'LPR_BASE_DATE' and s.code_value = pq.lpr_base_date)lpr_base_date_n, pq.lpr_adjustment_period, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.FLOATING_RANGE_METHOD' and s.code_value = pq.lpr_adjustment_period)lpr_adjustment_period_n, pq.asset_mgt_fee_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'ASSET_MGT_FEE_TYPE' and s.code_value = pq.asset_mgt_fee_type)asset_mgt_fee_type_n, pq.interest_amortization_method, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'GLD.AMORTIZATION_METHOD' and s.code_value = pq.interest_amortization_method)interest_amortization_method_n, pq.rental_rounding_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'RENTAL_ROUNDING_TYPE' and s.code_value = pq.rental_rounding_type)rental_rounding_type_n, pq.calc_date_type, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CALC_DATE_TYPE' and s.code_value = pq.calc_date_type)calc_date_type_n, pq.rental_pay_date, pq.lpr_ref_day, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'LPR_DATE_REF' and s.code_value = pq.lpr_ref_day)lpr_ref_day_n, pq.vatable_rate_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.vatable_rate_flag)vatable_rate_flag_n, pq.vatable_prin_flag, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'SYS.YES_NO' and s.code_value = pq.vatable_prin_flag)vatable_prin_flag_n, pq.lpr_name_date, pq.xirr_net, pq.xirr_paynote, pq.xirr_net_paynote, pq.lease_times, pq.interest_year_days, pq.irr_after_tax, pq.irr, pq.total_rental, pq.total_interest, pq.apt_bill_ratio, pq.apt_bill_amount, pq.apt_bill_term, pq.lf_credit_ratio, pq.lf_credit_amount, pq.lf_credit_term, pq.cash_amount, pq.cash_ratio, pq.bonded_lease_flag, pq.base_rate_collect, (SELECT fb.description AS value_name FROM fnd_base_rate_set fb where fb.BASE_RATE_SET = pq.base_rate_collect) base_rate_collect_n, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.BONDED_LEASE_FLAG and scb.CODE = 'SYS.YES_NO') bonded_lease_flag_n, pq.deposit_deduction, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scvb.VALUE = pq.deposit_deduction and scb.CODE = 'PRJ.MARGIN_PAYMENT_METHOD')deposit_deduction_n, pq.lease_charge_ratio, pq.deposit_ratio, pq.down_payment_ratio, pq.float_type, (SELECT t.description AS value_name FROM fnd_tax_type_code t WHERE t.enabled_flag = 'Y' and t.tax_type_code = pq.tax_type_code )tax_type_code_n from PRJ_QUOTATION pq
1=1
and pq.source_Document_Id=#{sourceDocumentId}
and pq.source_document_category=#{sourceDocumentCategory}
and pq.quotation_id=#{quotationId}

select pp.business_type, pq.down_payment, case pq.down_payment_method when '10' then pq.down_payment when '20' then pq.down_payment_ratio end down_payment_tmp, pq.deposit, case pq.deposit_method when '10' then pq.deposit when '20' then pq.deposit_ratio end deposit_tmp, (select hbt.description from hls_business_type hbt where hbt.business_type = pp.business_type and hbt.document_category = pp.DOCUMENT_CATEGORY)business_type_n, (select s.MEANING from sys_code_value_b_v s where s.code = 'CON.FLOATING_RANGE_METHOD' and s.code_value = pq.floating_range_method) floating_range_method_n, (select s.MEANING from sys_code_value_b_v s where s.code = 'GRACE_TYPE' and s.code_value = pq.grace_type) grace_type_n, (select s.MEANING from sys_code_value_b_v s where s.code = 'PAY_METHOD' and s.code_value = pq.down_payment_method) down_payment_method_n, pq.down_payment_ratio, (select s.MEANING from sys_code_value_b_v s where s.code = 'PAY_METHOD' and s.code_value = pq.deposit_method) deposit_method_n, pq.deposit_ratio, pq.int_rate, pq.lease_charge_ratio, pq.repay_flag, pq.service_fee_repay_flag, (select s.MEANING from sys_code_value_b_v s where s.code = 'SYS.YES_NO' and s.code_value = pq.repay_flag) repay_flag_n, (select s.MEANING from sys_code_value_b_v s where s.code = 'SYS.YES_NO' and s.code_value = pq.service_fee_repay_flag) service_fee_repay_flag_n, (select s.MEANING from sys_code_value_b_v s where s.code = 'HLS500_ANNUAL_PAY_TIMES' and s.code_value = to_char(pq.annual_pay_times)) annual_pay_times_n,
pq.residual_value, pq.lease_term, (select s.MEANING from sys_code_value_b_v s where s.code = 'DEPOSIT_PROCESS' and s.code_value = pq.deposit_process) deposit_process_n,
pq.grace_flag, (select s.MEANING from sys_code_value_b_v s where s.code = 'EXEMPT_PENALTY_INT' and s.code_value = pq.grace_flag) grace_flag_n, pq.grace_period, pq.grace_month_one, pq.grace_month_two, pq.grace_month_three, pq.grace_month_four, pq.price_type, pq.purchase_tax, pq.insurance_premium, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRICE_TYPE' AND v.code_value = pq.price_type ) price_type_n, pq.lease_charge_times, pq.rental_principal_ratio1, pq.rental_principal_ratio2, pq.rental_principal_ratio3, pq.rental_principal_ratio4, pq.rental_principal_ratio5, pq.rental_principal_ratio6, pq.rental_principal_ratio7, pq.rental_principal_ratio8, pq.rental_principal_ratio9, pq.rental_principal_ratio10, pq.rental_principal_ratio11, pq.rental_principal_ratio12, pq.PAY_METHOD_DESC, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'GRACE_TYPE_SPECIAL' AND v.code_value = pq.grace_type_special) grace_type_special_n, pq.grace_type_special, pq.payment_type, pq.acceptance_term, pq.bank_deposit_ratio, pq.bank_lease_charge_ratio, pq.lease_charge_discount_num, pq.irr, pq.installed_capacity, pq.unit_price, pq.each_rental, pq.first_rent_flag, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ.PAYMENT_METHOD' AND v.code_value = pq.payment_type) payment_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ.ACCEPTANCE_TERM' AND v.code_value = pq.acceptance_term) acceptance_term_n from prj_project pp, prj_quotation pq where pp.project_id = pq.source_document_id and pq.source_document_category = 'PRJ_PROJECT' and pp.project_id = #{projectId}
